            file_id TEXT PRIMARY KEY,
            path TEXT NOT NULL UNIQUE,
            language TEXT NOT NULL,
            module TEXT NOT NULL,
            commit_id TEXT NOT NULL,
            blob_id TEXT NOT NULL,
            source_text TEXT NOT NULL
        );
